import { DataTable, useNarrow, type Column, type DataTableProps, type SortState, type TabsLook } from './DataTable'
import './demo.css'

export type TableWidgetProps<T> = {
  title: string
  /** Заголовок узлом вместо title (напр. переключатель стадии «Групповой этап / Плей-офф» — лаба rare-cases v4); title остаётся подписью таблицы */
  head?: ReactNode
  /** Подпись серым после заголовка (на телефоне не показываем) */
  sub?: string
  rows: T[]
  columns: Column<T>[]
  rowKey: (r: T) => string
  /** Сортировка по умолчанию — к ней возвращает «Сбросить» */
  def: SortState
  /** Поля фильтра (2–3); нет — кнопки «Фильтр» нет */
  fields?: FilterField<T>[]
  /** Своё в шапке слева от «Сбросить» (например, выбор позиции) */
  actions?: ReactNode
  /** false — без кнопки «Сбросить» в шапке (список турниров движка, лаба v28: шапка одна на два вида) */
  reset?: boolean
  /** На телефоне actions — отдельной строкой под шапкой, заголовок не жмётся (список турниров движка, лаба v39) */
  actionsBelow?: boolean
  narrow?: boolean
  tabsLook?: TabsLook
  phone?: 'tabs' | 'expand'
  status?: 'ready' | 'loading' | 'error'
  onRetry?: () => void
  /** Для историй: начальное значение фильтра */
  initial?: FilterValue
  className?: string
  /** Зоны таблицы (тон строк, черты) — пробрасываются в DataTable */
  zones?: Pick<DataTableProps<T>, 'rowTone' | 'rowState' | 'toneLook' | 'zones' | 'zoneLook'>
  /** Нажатие на строку */
  onRowClick?: (r: T) => void
  /** Пусто после фильтра — подпись (по умолчанию «Никого не нашли») */
  emptyText?: string
}
const NONE: never[] = []

/** Виджет-таблица (правила «Общие/Таблица/Правила», дирижёр 17.11): шапка «заголовок · подпись · [своё] [↺ Сбросить] [Фильтр]» + DataTable v4.
 *  Так собирается любая таблица страницы: колонки — ячейками из слотов, остальное — здесь. */
export function TableWidget<T>({ title, head, sub, rows, columns, rowKey, def, fields, actions, narrow: force, tabsLook, phone, status = 'ready', onRetry, initial, className, zones, onRowClick, emptyText, reset = true, actionsBelow }: TableWidgetProps<T>) {
  const f = useTableFilter((fields ?? NONE) as FilterField<T>[], rows, { value: initial })
  const { ref, narrow } = useNarrow(640, force)
  const [sort, setSort] = useState<SortState | null>(def)
  const isDef = sort?.key === def.key && sort.dir === def.dir && !f.count
  return (
    <div ref={ref} className={className}>
      <Widget head="line" fluid title={head ?? title} sub={narrow ? undefined : sub} actions={<>
        {!(actionsBelow && narrow) && actions}
        {reset && <Button variant="tonal" size="icon-lg" className="dt4-reset" aria-label="Сбросить сортировку и фильтр" title="Сбросить сортировку и фильтр" disabled={isDef || status !== 'ready'} onClick={() => { setSort(def); f.reset() }}><Icon name="reset" /></Button>}
        {fields && <TableFilter f={f} narrow={narrow} />}
      </>}>
        {actionsBelow && narrow && actions && <div className="dt4-ctl">{actions}</div>}
        <DataTable label={title} rows={f.rows} total={f.total} rowKey={rowKey} columns={columns} narrow={force} sort={def} sortValue={sort} {...zones} onSortChange={setSort}
          tabsLook={tabsLook} phone={phone} openFirst={phone === 'expand'} status={status} onRetry={onRetry} onRowClick={onRowClick} empty={emptyText} />
      </Widget>
    </div>
  )
}
