  const cols = useMemo(() => groupCols.filter((c) => c.key !== 'fin'), [])
  return <TableWidget title="Групповой этап" sub="TI 2026 · швейцарка · Bo3" rows={rows} columns={cols} rowKey={(r) => r.team} def={{ key: 'place', dir: 1 }} narrow={narrow}
    zones={{ rowTone: tone ? (r) => (r.place <= po ? 'up' : 'down') : undefined, toneLook, zones: line ? [{ after: po, label: '↑ Плей-офф   ↓ Выбыли' }] : undefined, zoneLook }} />
