import { TeamLogo } from '@/atoms/TeamLogo'
import type { FilterField } from '@/common/TableFilter'

export type PRow = { id: string; nick: string; team: string; teamName: string; pos: number; maps: number; wins: number; k: number; d: number; a: number; kda: number; gpm: number; xpm: number; lh: number; dmg: number; tdmg: number; move: number }
type Stat = { player: string; team: string; maps: number; wins: number; k: number; d: number; a: number; kda: number; gpm: number; xpm: number; lh: number; heroDmg: number; towerDmg: number; rank: number; prevRank: number }

