import { TierTag } from '@/atoms/TierTag'
import { NewsMore } from '../../More'
import { when, type NewsItem, type TitlePart } from '../../data'
import './NewsRow.css'

export type NewsRowProps = {
  item: NewsItem
  /** «Сейчас» для времени (мс); виджет обновляет раз в 20 с */
  now?: number
  /** Новая новость уже просмотрена — метка «Новое» гаснет */
  seen?: boolean
  /** Сразу раскрыта (для витрины): суть напечатана целиком */
  open?: boolean
}

export function NewsTitle({ parts }: { parts: TitlePart[] }) {
  return <>{parts.map((p, i) => typeof p === 'string' ? p : 'nb' in p
    ? <span key={i} className="news-row__nb">{p.nb[0]}<Mention {...p.nb[1]} />{p.nb[2]}</span>
    : <Mention key={i} {...p} />)}</>
}

/** Строка новости (лаба widget-news v73: n2-r): время и Tier сверху, заголовок с упоминаниями до 3 строк, «Подробнее», картинка 56 справа у части строк.
 *  «Подробнее» — суть печатается по словам на месте (reveal: 'type'), строка остаётся раскрытой. */
export function NewsRow({ item, now, seen, open: open0 }: NewsRowProps) {
  const words = item.lede.split(' ')
  const [open, setOpen] = useState(!!open0)
  const [k, setK] = useState(open0 ? words.length : 0)
  const t = useRef<ReturnType<typeof setTimeout>>(undefined)
  const typing = open && k < words.length
  useEffect(() => {
    if (!open || k >= words.length) return
    t.current = setTimeout(() => setK((x) => x + 1), k === 0 ? 500 : 45)
    return () => clearTimeout(t.current)
  }, [open, k, words.length])
  return (
    <div className={['news-row', item.img && 'has-img', open && 'is-open', typing && 'is-gen', seen && 'is-seen'].filter(Boolean).join(' ')}>
      <span className="news-row__b">
        <span className="news-row__m">
          <time>{when(item.ts, now)}</time>
          {item.fresh && <span className="news-row__new">Новое</span>}
          {item.tier && <TierTag tier={item.tier} />}
        </span>
        <span className="news-row__t"><NewsTitle parts={item.title} /></span>
        <span className="news-row__x">
          <span className="news-row__xi">
            {open && <>
              <span className="news-row__l"><span>{words.slice(0, k).join(' ')}</span>{typing && <span className="news-row__cur" />}</span>
              <ul className="news-row__pts" />
              {!typing && <a className="news-row__go" href="#" onClick={(e) => e.preventDefault()}>Читать ›</a>}
              <i className="news-row__wave" />
            </>}
          </span>
        </span>
        <NewsMore open={open} onClick={() => setOpen(true)} />
      </span>
      {item.img && <img className="news-row__im" src={item.img} alt="" loading="lazy" />}
    </div>
  )
}
