export function FilterChips<T>({ f }: { f: TableFilterState<T> }) {
  const chips = f.fields.flatMap((fd) => {
    const v = f.value[fd.key]
    if (!isOn(v)) return []
    const name = (x: string) => fd.options?.find((o) => o.value === x)?.label ?? x
    if (Array.isArray(v)) return v.map((x) => ({ k: fd.key + ':' + x, label: <>{fd.label}: {name(x)}</>, off: () => f.set(fd.key, v.filter((y) => y !== x)) }))
    return [{ k: fd.key, label: fd.type === 'search' ? <>«{v}»</> : <>{fd.label}: {name(v)}</>, off: () => f.set(fd.key, '') }]
  })
  if (!chips.length) return null
  return (
    <div className="tf-chips">
      {chips.map((c) => <Button key={c.k} variant="chip" size="sm" pressed className="tf-chips__c" onClick={c.off} aria-label="Убрать фильтр">{c.label}<Icon name="close" /></Button>)}
      <Button variant="link" size="sm" onClick={f.reset}>Сбросить</Button>
    </div>
  )
}

/** Панель фильтра — одна на все таблицы, по умолчанию скрыта. На компьютере — под шапкой виджета, на телефоне — шторка снизу. */
export function FilterPanel<T>({ f, narrow }: { f: TableFilterState<T>; narrow?: boolean }) {
  if (!f.open) return null
  const fields = f.fields.map((fd) => {
    const v = f.value[fd.key]
    let ctl: ReactNode
    if (fd.type === 'search') ctl = (
      <label className="tf-search"><Icon name="search" />
        <input type="search" value={(v as string) ?? ''} placeholder={fd.placeholder ?? 'Поиск'} aria-label={fd.label} onChange={(e) => f.set(fd.key, e.target.value)} />
      </label>
    )
    else if (fd.type === 'segment') ctl = <Segment size="sm" fill={narrow} value={(v as string) ?? ''} onChange={(x) => f.set(fd.key, x)} options={[{ value: '', label: 'Все' }, ...(fd.options ?? [])]} />
    else {
      const a = (v as string[]) ?? []
      ctl = <div className="tf-opts">{fd.options?.map((o) => <Button key={o.value} variant="chip" size="sm" pressed={a.includes(o.value)} onClick={() => f.set(fd.key, a.includes(o.value) ? a.filter((x) => x !== o.value) : [...a, o.value])}>{o.label}</Button>)}</div>
    }
    return <div key={fd.key} className={'tf-f tf-f--' + fd.type}><span className="tf-f__l">{fd.label}</span>{ctl}</div>
  })
  if (!narrow) return (
    <div className="tf-panel" role="region" aria-label="Фильтр">
      {fields}
      <div className="tf-panel__ft">
        <span className="tf-panel__n">Найдено: {f.rows.length} из {f.total}</span>
        <Button variant="tonal" size="sm" disabled={!f.count} onClick={f.reset}><Icon name="reset" />Сбросить</Button>
        <Button variant="ghost" size="icon-sm" aria-label="Закрыть фильтр" onClick={() => f.setOpen(false)}><Icon name="close" /></Button>
      </div>
    </div>
  )
  return (
    <div className="tf-sheet" role="dialog" aria-modal="true" aria-label="Фильтр">
      <div className="tf-sheet__ov" onClick={() => f.setOpen(false)} />
      <div className="tf-sheet__in">
        <div className="tf-sheet__grab" />
        <div className="tf-sheet__hd"><b>Фильтр</b><Button variant="ghost" size="icon-sm" aria-label="Закрыть фильтр" onClick={() => f.setOpen(false)}><Icon name="close" /></Button></div>
        {fields}
        <div className="tf-sheet__ft">
          <Button variant="secondary" size="xl" disabled={!f.count} onClick={f.reset}>Сбросить</Button>
          <Button variant="primary" size="xl" onClick={() => f.setOpen(false)}>Показать {f.rows.length}</Button>
        </div>
      </div>
    </div>
  )
}
