  // телефон: «Свернуть» — в строку; «Развернуть» — из строки, а если строка от прокрутки — наверх страницы (кнопка не прыгает)
  const toggle = () => { if (folded) setFolded(false); else if (auto) window.scrollTo({ top: 0, behavior: 'smooth' }); else setFolded(true) }
  const h = tourHead(tour)
