        <span className="mc__n">{id ? <EntityTag kind="team" id={id} label={<b>{teamName(id)}</b>} /> : <b>{lb}</b>}{id && s?.form && <SlotView s={{ t: 'form', res: s.form.slice(0, 5).map((f) => (f.win ? 'w' : 'l')), of: 5 }} />}</span>
