          <div className="mc__lb mc__lb--sk" title="Счёт серии"><SIcon name="skull" size={12} /></div>
          {L ? <div className="mc__lvh"><span>Убийства</span><span>Золото</span><span>Башни</span><span /><span>Перевес</span></div> : <span />}
