export default meta
type S = StoryObj<typeof LiveStrip>
export const TI: S = { name: 'TI 2026 · идёт', args: { tour: 'ti' } }
export const Universe: S = { name: 'Universe Ep. 7 · прошёл', args: { tour: 'ep7' } }
