    const out: string[] = []; for (let d = new Date(lo + '-01T00:00:00Z'); iso(d).slice(0, 7) <= hi; d = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 1))) out.push(iso(d).slice(0, 7))
