  const root = useRef<HTMLElement>(null), [fill, setFill] = useState<number | null>(null)
  useLayoutEffect(() => { if (height != null) return; const upd = () => { const el = root.current; if (el) setFill(Math.max(560, innerHeight - el.getBoundingClientRect().top - window.scrollY - 16)) }
    upd(); addEventListener('resize', upd); return () => removeEventListener('resize', upd) }, [height])
  // анонс, перенос, отмена — карты нет, в лабе открыта только «Статистика»
  if (mcase === 'announce' || mcase === 'delayed' || mcase === 'cancel') return null
