  const FC = !win && now < 720, bX = FC ? 720 + LANE_TAIL : bE
  const secs = [a0]; for (let s = Math.floor(a0 / 60) * 60 + 60; s < bE; s += 60) secs.push(s); secs.push(bE)
  // прогноз: весь 0–12′ от нуля, реальный график идёт поверх (fcAll)
