  if (FC) for (let s = 0; ; s = Math.min(720, s + 20)) { fcP.push([s, fr(s)]); if (s >= 720) break }
  const vals = secs.map(at).concat(fcP.map((q) => q[1]))
  let hi = Math.max(0, ...vals), lo = Math.min(0, ...vals); const pad = Math.max(200, (hi - lo) * 0.04); hi += pad; lo -= pad
  const step = [500, 1000, 2000, 5000, 10000, 20000].find((s) => (hi - lo) / s <= (H > 400 ? 6 : 4)) || 20000
  // поле справа — по самой широкой подписи (метка значения или число шкалы)
  const tw = (s: string) => [...s].reduce((a, c) => a + (c === '.' ? 3 : c === 'k' ? 6 : 6.6), 0)
