  const ans = pick != null, left = due && !res ? Math.max(0, due[1] - now) : 0, isDue = left > 0, pt = ans ? pts(x.o[pick].pct) : 0
  const open = !ans && !res, st = res ? 'is-' + res : ans ? 'is-ans' : 'is-open'
