import { Predictions } from './Predictions'
import { MATCH_STATES } from '../../state'

/** Виджет живой: ответ, «Закрыть», стрелки по кругу, через 1 с — следующая карточка; всё отвечено или закрыто — итог, решается раз в 5 с.
 *  Сценарий — ось «Прогнозы» песочницы: ждём событие · пришло событие · накопились · 3 · всё собрано. */
const meta: Meta<typeof Predictions> = { title: 'Сайт/Матч/Прогнозы/Predictions v2', component: Predictions, parameters: { layout: 'padded' }, args: { state: 'live', viewer: 'in', scenario: 'one' },
  argTypes: {
    state: { ...stateArg(), description: 'Состояние матча: виджет есть только в лайве (live12 · live), до и после матча его нет' },
    viewer: { ...viewerArg, description: 'Зритель: in — вошёл · guest — гость (видит то же, что вошедший)' },
    scenario: { control: 'inline-radio', options: ['wait', 'one', 'many', 'done'], description: 'Что пришло к этой минуте: wait — ждём событие · one — пришло событие · many — накопились три · done — всё отвечено' },
    init: { control: 'object', description: 'Стартовое состояние для историй: pick — ответы, skip — закрытые, i — открытая карточка, allDone — открыт итог, resAgo — сколько мс назад начали решаться' },
    ...statusArgTypes,
  } }
export default meta
type S = StoryObj<typeof Predictions>

export const ПришлоСобытие: S = { name: 'Пришло событие (по умолчанию)' }
export const Колода: S = { name: 'Колода · накопились 3', args: { scenario: 'many' } }
export const Ответил: S = { args: { scenario: 'many', init: { pick: { rosh: 0 } } } }
export const Закрыл: S = { args: { scenario: 'many', init: { skip: { rosh: true }, i: 1 } } }
export const ВсеОтвечены: S = { name: 'Все отвечены — решаются', args: { scenario: 'done' } }
export const Итог: S = { args: { scenario: 'many', init: { pick: { rosh: 0, map: 1 }, skip: { die: true }, allDone: true, resAgo: 20000 } } }
export const ЖдёмСобытие: S = { name: 'Ждём событие', args: { scenario: 'wait' } }
export const Гость: S = { name: 'Гость (как у вошедшего)', args: { viewer: 'guest' } }

/** По состояниям матча: виджет есть только в лайве (Первые 12′ · Live); до матча (До матча · Драфт · Пики готовы) и после — его нет */
const byState = (i: number): S => ({ name: 'Матч: ' + MATCH_STATES[i].label + (['live12', 'live'].includes(MATCH_STATES[i].value) ? '' : ' — виджета нет'), args: { state: MATCH_STATES[i].value } })
export const ДоМатча = byState(0)
export const Драфт = byState(1)
export const ПикиГотовы = byState(2)
export const Первые12 = byState(3)
export const Live = byState(4)
export const После = byState(5)

