export function useMapNow(state: MatchState, fixed?: number | null) {
  const { map, t } = MAP_OF_STATE[state]
  const run = fixed == null && LIVE.includes(state)
  const [now, setNow] = useState(t)
  useEffect(() => {
    setNow(t)
    if (!run) return
    const t0 = performance.now()
    const id = setInterval(() => setNow(Math.min(map.duration, t + ((performance.now() - t0) / 1000) * GLIDE)), 1000 / 30)
    return () => clearInterval(id)
  }, [state, run, t, map.duration])
  return fixed ?? now
}
