export type MapAt = { map: MapData; /** номер карты в серии */ n: number; /** секунда игры («сейчас») */ t: number }
export const MAP_OF_STATE: Record<MatchState, MapAt> = {
  pre0: { map: MAPS[8957527957], n: 1, t: 0 },
  draft: { map: MAPS[8957527957], n: 1, t: 0 },
  pre: { map: MAPS[8957527957], n: 1, t: 0 },
  live12: { map: MAPS[8957364447], n: 3, t: 510 },
  live: { map: MAPS[8957364447], n: 3, t: 2010 },
  post: { map: MAPS[8956877335], n: 3, t: 2503 },
}

/** Карты серии по номеру вкладки (1…N) — в каждом состоянии (лаба: клик по «Map 1» / «Map 2» в шапке открывает график той карты). */
