/** Вкладка «Статистика» страницы матча (лаба gs-match-2/v86-draft.html, вкладка «Статистика»).
 *  Считается из window.GS_DATA (gs-match/data/_matches.js) и базы, как в лабе: «Эта серия» (w-stats-2/_wsg.js + w-lanemap/_lm.js), «MVP серии».
 *  Снимком — только то, чего в GS_DATA нет (лаба считает это по всему турниру, GS_TOURNAMENT, и своей модели): «О матче» (шансы — ‼️ пример),
 *  «На турнире», числа «Составов». Имена команд, ники, герои — из базы (дирижёр 12.11: «везде из базы»).
 *  Наборы: до матча (pre0, draft, pre) — одни данные; идёт (live12, live) — одни, кроме «Этой серии» (минута идущей карты); после (post) — свои. */
import type { MatchCase, MatchState } from '../state'

const T_1W = teamName(10150413)

export type Side = 'a' | 'b'
/** «О матче»: строка-показатель — значения команд, чья лучше, плашка с перевесом и полоса */
export type AboutRow = { icon: 'map' | 'flame' | 'flag' | 'trophy' | 'clock'; side: Side; label: string; a: string; b: string; best: number
  chip: { side: Side; team: number; value: string }; /** ширина первой части полосы, % */ bar: number; barBest: number }
export type AboutData = { sub: string; teams: { team: number; name: string }[]; big: string[]; bigNote: string; bigBest: number; bar: number; barBest: number
  rows: AboutRow[]; sum: { team: number; note: string; title: string; text: string } }
export type LineupRow = { /** id игрока в базе */ player: string; pos: number; nick: string; hero: string; heroName: string; value: string; title: string; top: boolean }
export type LineupsData = { title: string; sub: string; cols: { team: number; name: string; rows: LineupRow[] }[] }
export type TourTile = { value: string; of: string | null; label: string; best: boolean }
export type TourGame = { win: boolean; title: string; score: string }
export type TournamentData = { title: string; sub: string; h2h: { text: string; score: string | null }
  cols: { team: number; name: string; sub: string; form: string; tiles: TourTile[]; games: TourGame[] }[] }
export type SeriesPick = { hero: string; title: string; order: number; nick: string; /** нетворс на конец карты; идущая карта — null */ nw: string | null; top: boolean }
export type SeriesBan = { hero: string; title: string; order: number }
export type SeriesSide = { team: number; name: string; side: 'r' | 'd'; win: boolean; picks: SeriesPick[]; bans: SeriesBan[] }
export type LaneHero = { hero: string; side: 'r' | 'd'; /** место на карте, % */ left: number; top: number; title: string; role: number; roleTitle: string; nw: string | null }
export type LaneAdv = { side: 'r' | 'd'; text: string; title: string; left: number; top: number }
export type SeriesMap = { name: string; state: string; live: boolean; /** победитель — id команды */ win: number | null
  gold: { a: string; b: string; on: number; pct: number } | { wait: string }
  sides: SeriesSide[]; map: { nw: boolean; /** порядок на карте (кто кого перекрывает): h — герой, a — перевес линии */ seq: string; heroes: LaneHero[]; adv: LaneAdv[] } }
export type SeriesData = { title: string; sub: string; maps: SeriesMap[] }
export type MvpData = { title: string; sub: string; player: string; nick: string; team: number; teamName: string; stats: { value: string; label: string }[]; heroes: { hero: string; label: string }[] }

