export type FeedItem = { t: string; title: string; views: number; com: number; img: string; url: string; lede: string; db: string }
export type NewsItem = FeedItem & { tour: 'uni' | 'etc'; fresh?: boolean }
export type DbNews = { id: string; teams: string[]; players: string[]; tours: string[] }
export type Match = { id: string; a: string; b: string; state: 'live' | 'soon' | 'done'; start: string; score?: [number, number]; live?: string; stage?: string }

declare global { interface Window { NEWS_FEED: FeedItem[] } }

const MON = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря']
const MS = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек']
const DAYS = ['Воскресенье', 'Понедельник', 'Вторник', 'Среда', 'Четверг', 'Пятница', 'Суббота']

type DBx = { logo: (x: string) => string | null; name: (x: string, k?: 'name' | 'mid' | 'tag') => string }
const X = () => DB() as unknown as DBx
/** Лого команды по id/имени (адрес) */
export const logoOf = (id: string) => X().logo(id) ?? ''
/** Имя команды: полное · среднее · тег */
export const nameOf = (id: string, k: 'name' | 'mid' | 'tag' = 'name') => X().name(id, k)

let cache: ReturnType<typeof build> | null = null
