  const used = new Set(D.news.flatMap((n) => n.teams)), usedP = new Set(D.news.flatMap((n) => n.players))
  for (const id of used) { const t = D.teams[id]; for (const x of [...new Set([t.name, t.mid])].filter((x) => x.length > 2)) ALIAS.push([x, 't', t.name]) }
