    nb(n).teams.forEach((id) => { const x = DB().team(id); if (!x) return; [x.name, x.mid, x.tag].filter((v, i, a): v is string => !!v && v.length > 2 && a.indexOf(v) === i).forEach((w) => W.push([w, { kind: 'e', text: w, img: logoOf(id) || undefined }])) })
    nb(n).players.forEach((id) => { const q = DB().player(id); if (q && q.nick && q.nick.length > 2) W.push([q.nick, { kind: 'p', text: q.nick, img: q.photo ? DB().url(q.photo) ?? undefined : undefined }]) })
    if (!W.length) return [n.title]; W.sort((x, y) => y[0].length - x[0].length)
