export type NewsFilter = { match?: string | null; topic?: string | null }
export const filterFn = (f: NewsFilter) => { const d = newsData(), m = f.match ? d.MM.find((x) => x.id === f.match) : null, t = f.topic ? d.TOPICS.find((x) => x.id === f.topic) : null
  return (n: NewsItem) => (m ? d.inM(m)(n) : t ? t.t(n) : true) }

/** Три колонки матча: обе команды · первая · вторая — свежие сверху, по 6 */
export const matchColumns = (m: Match): MatchColumn[] => { const d = newsData(), has = (id: string) => (n: NewsItem) => d.nb(n).teams.includes(id), L = d.tm(d.F.filter(d.inM(m)))
  const cols: [string, string[], NewsItem[]][] = [
    ['Обе команды', [logoOf(m.a), logoOf(m.b)], L.filter((n) => has(m.a)(n) && has(m.b)(n))],
    [d.teamName(m.a, 'mid'), [logoOf(m.a)], L.filter((n) => has(m.a)(n) && !has(m.b)(n))],
    [d.teamName(m.b, 'mid'), [logoOf(m.b)], L.filter((n) => has(m.b)(n) && !has(m.a)(n))]]
  return cols.map(([title, logos, l]) => ({ title, logos, count: l.length, items: l.slice(0, 6).map(rowOf) })) }
export const matchColumnsUsed = (m: Match) => { const d = newsData(), has = (id: string) => (n: NewsItem) => d.nb(n).teams.includes(id), L = d.tm(d.F.filter(d.inM(m)))
  return new Set([L.filter((n) => has(m.a)(n) && has(m.b)(n)).slice(0, 6), L.filter((n) => has(m.a)(n) && !has(m.b)(n)).slice(0, 6), L.filter((n) => has(m.b)(n) && !has(m.a)(n)).slice(0, 6)].flat()) }

