import type { TourKey } from '../../state'
import { SkeletonLines, StatusError, type WidgetStatus } from '@/atoms/WidgetStatus'
import './Format.css'

export type FormatProps = {
  tour: TourKey
  /** Нажали «Правила тай-брейков ›» */
  onRules?: () => void
  /** Состояние данных (по умолчанию ready) */
  status?: WidgetStatus
  /** «Повторить» в состоянии error */
  onRetry?: () => void
}

/** «Формат» (лаба gs-tournament/_ours.js, TN_FMT 'steps'): этапы шагами по датам — пройденные залиты, правила одной строкой; «Правила тай-брейков ›». */
export function Format({ tour, onRules, status = 'ready', onRetry }: FormatProps) {
  if (status !== 'ready') return <Widget head="card" fluid className="tfmt-card" title="Формат">{status === 'loading' ? <SkeletonLines n={6} widths={['55%', '90%']} gap={12} /> : <StatusError onRetry={onRetry} />}</Widget>
  return (
    <Widget head="card" fluid className="tfmt-card" title="Формат">
      <ol className="tfmt">
        {tourFormat(tour).map((s) => (
          <li key={s.name} className={'tfmt__step' + (s.done ? ' tfmt__step--done' : '')}>
            <i className="tfmt__dot" />
            <div className="tfmt__h"><b>{s.name}</b><small>{s.dates}</small></div>
            <p className="tfmt__rules">{s.rules.map((r, i) => <Fragment key={i}>{i > 0 && ' · '}{r.split(/\\*\\*(.+?)\\*\\*/).map((x, j) => (j % 2 ? <mark key={j} className="tfmt__mark">{x}</mark> : x))}</Fragment>)}</p>
          </li>
        ))}
      </ol>
      <a className="tfmt__more" href="#" onClick={(e) => { e.preventDefault(); onRules?.() }}>Правила тай-брейков ›</a>
    </Widget>
  )
}
