import { Skeleton } from '@/atoms/Skeleton'
import type { TourKey } from '../../state'
import { StatusError, type WidgetStatus } from '@/atoms/WidgetStatus'
import './TourHeader.css'

export type TourHeaderProps = {
  tour: TourKey
  /** Нажали «‹» — назад */
  onBack?: () => void
  /** Состояние данных (по умолчанию ready) */
  status?: WidgetStatus
  /** «Повторить» в состоянии error */
  onRetry?: () => void
}

/** Шапка турнира (лаба gs-tournament v46 .th): «‹», лого, название и подпись; справа строкой — тир, даты, команд, призовой, организатор, тип, победитель / патч. Прилипает под шапкой сайта. */
export function TourHeader({ tour, onBack, status = 'ready', onRetry }: TourHeaderProps) {
  const h = tourHead(tour)
  const back = <a className="thd__back" href="#" aria-label="Назад" onClick={(e) => { e.preventDefault(); onBack?.() }}>‹</a>
  if (status !== 'ready') return (
    <section className="thd">
      <div className="thd__row">
        {back}
        {status === 'loading'
          ? <><Skeleton shape="block" width={72} height={40} /><div className="thd__t thd__t--skel"><Skeleton width={220} height={18} /><Skeleton width={160} /></div>
              <div className="thd__info"><div className="thd__kv">{[0, 1, 2, 3, 4, 5].map((i) => <div key={i} className="thd__t--skel"><Skeleton width={56} /><Skeleton width={80} /></div>)}</div></div></>
          : <StatusError inline onRetry={onRetry} />}
      </div>
    </section>
  )
  return (
    <section className="thd">
      <div className="thd__row">
        {back}
        {h.logo && <img className="thd__logo" src={h.logo} alt="" />}
        <div className="thd__t"><b>{h.name}</b><small>{h.sub}</small></div>
        <div className="thd__info">
          <dl className="thd__kv">
            {h.info.map((x) => (
              <div key={x.k}><dt>{x.k}</dt><dd>{x.tag ? <span className="thd__tag">{x.v}</span> : x.v}{x.note && <> <small>{x.note}</small></>}</dd></div>
            ))}
          </dl>
        </div>
      </div>
    </section>
  )
}
